package ai.patnub.data

import ai.patnub.data.local.BundledContent
import java.io.File

/** The real content the app ships (generated by content/build.py). Tests run from the app module. */
object Bundled {
    val knowledge by lazy { BundledContent.parseKnowledge(File("src/main/assets/content/knowledge.json").readText()) }
    val medicines by lazy { BundledContent.parseMedicines(File("src/main/assets/content/medicines.json").readText()) }
}
